const CSS = "/* ===== FUNDOS, QUIZ E AJUSTES (novidades.js) ===== */\n\n[hidden] {\n    display: none !important;\n}\n\n/* Fundo da área de Biologia Marinha */\nbody:has(.marinha) {\n    background-color: #0c2830;\n    background-image: url(\"imagens/fundo-biologia.png\");\n    background-repeat: no-repeat;\n    background-position: center bottom;\n    background-size: 100% auto;\n    background-attachment: fixed;\n}\n\n/* Fundo da área dos Dinossauros */\nbody:has(.dinossauros) {\n    background-color: #103a21;\n    background-image: url(\"imagens/fundo-dinossauros.png\");\n    background-repeat: no-repeat;\n    background-position: center bottom;\n    background-size: 100% auto;\n    background-attachment: fixed;\n}\n\n/* Fotos que estavam cortadas: mostrar inteiras */\n.card img[src*=\"pinguim-imperador\"],\n.card img[src*=\"tartaruga-de-couro\"],\n.card img[src*=\"tubarao-baleia\"],\n.especie-imagem img[src*=\"pinguim-imperador\"],\n.especie-imagem img[src*=\"tartaruga-de-couro\"],\n.especie-imagem img[src*=\"tubarao-baleia\"] {\n    object-fit: contain;\n    background-color: #061f26;\n}\n\n/* QUIZ */\n.quiz-escolha {\n    display: flex;\n    justify-content: center;\n    gap: 30px;\n    margin-top: 40px;\n    flex-wrap: wrap;\n}\n\n.quiz-area {\n    width: 300px;\n    padding: 30px;\n    box-sizing: border-box;\n    border: none;\n    border-radius: 15px;\n    background-color: #0b3d4f;\n    color: white;\n    font-family: inherit;\n    cursor: pointer;\n}\n\n.quiz-area:hover {\n    background-color: #126579;\n    transform: translateY(-5px);\n}\n\n.quiz-area-dino {\n    background-color: #304332;\n}\n\n.quiz-area-dino:hover {\n    background-color: #435c42;\n}\n\n.quiz-area h3 {\n    font-size: 24px;\n    margin-top: 0;\n}\n\n.quiz-area p {\n    line-height: 1.5;\n    color: #d7f3f0;\n}\n\n.quiz-area-dino p {\n    color: #e8dfc5;\n}\n\n.quiz-recorde {\n    display: block;\n    min-height: 1.2em;\n    font-size: 15px;\n    color: #d9c98c;\n}\n\n.quiz-caixa {\n    max-width: 720px;\n    margin: 30px auto;\n    padding: 30px;\n    box-sizing: border-box;\n    background-color: #0b3d4f;\n    border-radius: 15px;\n    text-align: left;\n}\n\n.dinossauros .quiz-caixa {\n    background-color: #304332;\n}\n\n.quiz-topo {\n    display: flex;\n    justify-content: space-between;\n    font-size: 16px;\n    color: #d7f3f0;\n}\n\n.dinossauros .quiz-topo {\n    color: #e8dfc5;\n}\n\n.quiz-barra {\n    height: 10px;\n    margin: 12px 0 25px;\n    background-color: rgba(255, 255, 255, 0.15);\n    border-radius: 6px;\n    overflow: hidden;\n}\n\n#quiz-barra-cheia {\n    height: 100%;\n    width: 0;\n    background-color: #3fb8c9;\n    transition: width 0.3s;\n}\n\n.dinossauros #quiz-barra-cheia {\n    background-color: #d9c98c;\n}\n\n.quiz-caixa h2 {\n    margin-top: 0;\n    font-size: 26px;\n    line-height: 1.3;\n}\n\n.quiz-opcoes {\n    display: grid;\n    gap: 12px;\n    margin: 25px 0;\n}\n\n.quiz-opcao {\n    padding: 14px 18px;\n    text-align: left;\n    font-family: inherit;\n    font-size: 17px;\n    color: white;\n    background-color: rgba(255, 255, 255, 0.08);\n    border: 2px solid #126579;\n    border-radius: 10px;\n    cursor: pointer;\n}\n\n.quiz-opcao:hover:not(:disabled) {\n    background-color: #126579;\n}\n\n.dinossauros .quiz-opcao {\n    border-color: #435c42;\n    color: #e8dfc5;\n}\n\n.dinossauros .quiz-opcao:hover:not(:disabled) {\n    background-color: #435c42;\n}\n\n.quiz-opcao:disabled {\n    cursor: default;\n}\n\n.quiz-opcao.certa {\n    background-color: #1f7a4d;\n    border-color: #34c27a;\n    color: white;\n}\n\n.quiz-opcao.errada {\n    background-color: #7a2a2a;\n    border-color: #d65a5a;\n    color: white;\n}\n\n.quiz-explicacao {\n    padding: 14px 18px;\n    line-height: 1.5;\n    background-color: rgba(0, 0, 0, 0.25);\n    border-radius: 10px;\n}\n\n.quiz-botao {\n    padding: 12px 24px;\n    font-family: inherit;\n    font-size: 17px;\n    font-weight: bold;\n    color: #061f26;\n    background-color: #d7f3f0;\n    border: none;\n    border-radius: 10px;\n    cursor: pointer;\n}\n\n.quiz-botao:hover {\n    background-color: white;\n}\n\n.dinossauros .quiz-botao {\n    background-color: #d9c98c;\n    color: #17231a;\n}\n\n.quiz-botao-sec {\n    background-color: transparent;\n    color: white;\n    border: 2px solid #d7f3f0;\n}\n\n.dinossauros .quiz-botao-sec {\n    background-color: transparent;\n    color: #e8dfc5;\n    border-color: #d9c98c;\n}\n\n.quiz-placar {\n    font-size: 24px;\n    font-weight: bold;\n}\n\n.quiz-acoes {\n    display: flex;\n    gap: 15px;\n    flex-wrap: wrap;\n    margin-top: 25px;\n}\n";
const QUIZ_HTML = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Quiz</title>\n\n    <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n\n<body>\n\n    <header>\n        <h1>Quiz</h1>\n\n        <nav>\n            <a href=\"index.html\">Início</a>\n            <a href=\"biologia.html\">Biologia Marinha</a>\n            <a href=\"dinossauros.html\">Dinossauros</a>\n            <a href=\"quiz.html\">Quiz</a>\n        </nav>\n    </header>\n\n    <main id=\"quiz\">\n\n        <section id=\"tela-escolha\">\n            <h2>Teste seus conhecimentos</h2>\n            <p>Escolha uma área. Cada rodada tem 10 perguntas sorteadas.</p>\n\n            <div class=\"quiz-escolha\">\n                <button type=\"button\" class=\"quiz-area\" data-area=\"biologia\">\n                    <h3>🌊 Biologia Marinha</h3>\n                    <p>Perguntas sobre os animais dos oceanos.</p>\n                    <span class=\"quiz-recorde\" id=\"recorde-biologia\"></span>\n                </button>\n\n                <button type=\"button\" class=\"quiz-area quiz-area-dino\" data-area=\"dinossauros\">\n                    <h3>🦖 Dinossauros</h3>\n                    <p>Perguntas sobre os gigantes do passado.</p>\n                    <span class=\"quiz-recorde\" id=\"recorde-dinossauros\"></span>\n                </button>\n            </div>\n        </section>\n\n        <section id=\"tela-pergunta\" class=\"quiz-caixa\" hidden>\n            <div class=\"quiz-topo\">\n                <span id=\"quiz-progresso\"></span>\n                <span id=\"quiz-pontos\"></span>\n            </div>\n            <div class=\"quiz-barra\"><div id=\"quiz-barra-cheia\"></div></div>\n\n            <h2 id=\"quiz-enunciado\"></h2>\n\n            <div id=\"quiz-opcoes\" class=\"quiz-opcoes\"></div>\n\n            <p id=\"quiz-explicacao\" class=\"quiz-explicacao\" hidden></p>\n\n            <button type=\"button\" id=\"quiz-proxima\" class=\"quiz-botao\" hidden>Próxima pergunta →</button>\n        </section>\n\n        <section id=\"tela-final\" class=\"quiz-caixa\" hidden>\n            <h2>Resultado</h2>\n            <p id=\"quiz-placar\" class=\"quiz-placar\"></p>\n            <p id=\"quiz-mensagem\"></p>\n            <p id=\"quiz-recorde-final\" class=\"quiz-recorde\"></p>\n\n            <div class=\"quiz-acoes\">\n                <button type=\"button\" id=\"quiz-repetir\" class=\"quiz-botao\">Jogar de novo</button>\n                <button type=\"button\" id=\"quiz-trocar\" class=\"quiz-botao quiz-botao-sec\">Trocar de área</button>\n            </div>\n        </section>\n\n    </main>\n\n    <script src=\"quiz.js\"></script>\n\n</body>\n\n</html>\n";
const QUIZ_JS = "// quiz.js — lógica do quiz (gerado por novidades.js)\n// Para ADICIONAR perguntas, acrescente um item em PERGUNTAS.biologia ou PERGUNTAS.dinossauros:\n//   { p: \"Pergunta?\", o: [\"Certa\", \"Errada 1\", \"Errada 2\", \"Errada 3\"], c: 0, e: \"Explicação.\" }\n// \"c\" é a posição (começando em 0) da resposta certa dentro de \"o\". As opções são embaralhadas sozinhas.\n\nconst PERGUNTAS = {\n  \"biologia\": [\n    {\n      \"p\": \"Qual é o maior animal que existe atualmente?\",\n      \"o\": [\n        \"Baleia-azul\",\n        \"Tubarão-baleia\",\n        \"Lula-gigante\",\n        \"Orca\"\n      ],\n      \"c\": 0,\n      \"e\": \"A baleia-azul pode passar de 30 metros de comprimento e é o maior animal conhecido que já viveu.\"\n    },\n    {\n      \"p\": \"Do que a baleia-azul se alimenta principalmente?\",\n      \"o\": [\n        \"Krill\",\n        \"Tubarões\",\n        \"Algas\",\n        \"Lulas\"\n      ],\n      \"c\": 0,\n      \"e\": \"O krill são pequenos animais parecidos com camarões.\"\n    },\n    {\n      \"p\": \"Qual é o maior peixe do mundo?\",\n      \"o\": [\n        \"Tubarão-baleia\",\n        \"Tubarão-branco\",\n        \"Marlim-azul\",\n        \"Raia-manta\"\n      ],\n      \"c\": 0,\n      \"e\": \"O tubarão-baleia pode passar de 12 metros e se alimenta filtrando plâncton.\"\n    },\n    {\n      \"p\": \"Quantos braços tem um polvo?\",\n      \"o\": [\n        \"6\",\n        \"8\",\n        \"10\",\n        \"12\"\n      ],\n      \"c\": 1,\n      \"e\": \"O polvo tem oito braços cobertos de ventosas.\"\n    },\n    {\n      \"p\": \"Onde vive o pinguim-imperador?\",\n      \"o\": [\n        \"Antártida\",\n        \"Ártico\",\n        \"Ilhas Galápagos\",\n        \"Costa do Brasil\"\n      ],\n      \"c\": 0,\n      \"e\": \"É a maior espécie de pinguim e vive na Antártida, adaptado ao frio extremo.\"\n    },\n    {\n      \"p\": \"Qual é a maior tartaruga marinha do mundo?\",\n      \"o\": [\n        \"Tartaruga-de-couro\",\n        \"Tartaruga-verde\",\n        \"Tartaruga-de-pente\",\n        \"Tartaruga-oliva\"\n      ],\n      \"c\": 0,\n      \"e\": \"A tartaruga-de-couro tem uma carapaça flexível, parecida com couro, e não um casco duro.\"\n    },\n    {\n      \"p\": \"Nos cavalos-marinhos, quem carrega os filhotes?\",\n      \"o\": [\n        \"O macho\",\n        \"A fêmea\",\n        \"Os dois, em revezamento\",\n        \"Ninguém: os ovos ficam soltos no mar\"\n      ],\n      \"c\": 0,\n      \"e\": \"O macho guarda os ovos em uma bolsa e é ele quem libera os filhotes.\"\n    },\n    {\n      \"p\": \"Entre o que o peixe-palhaço costuma viver protegido?\",\n      \"o\": [\n        \"Anêmonas-do-mar\",\n        \"Esponjas\",\n        \"Algas gigantes\",\n        \"Corais mortos\"\n      ],\n      \"c\": 0,\n      \"e\": \"Ele vive entre os tentáculos das anêmonas, que o protegem de predadores.\"\n    },\n    {\n      \"p\": \"O que a lontra-marinha faz com pedras?\",\n      \"o\": [\n        \"Usa como ferramenta para abrir moluscos\",\n        \"Constrói a própria casa\",\n        \"Engole para mergulhar mais fundo\",\n        \"Usa para afiar os dentes\"\n      ],\n      \"c\": 0,\n      \"e\": \"Ela apoia a pedra no peito e bate os moluscos nela para abri-los.\"\n    },\n    {\n      \"p\": \"Por que o náutilo é chamado de “fóssil vivo”?\",\n      \"o\": [\n        \"Seu grupo existe há centenas de milhões de anos e mudou pouco\",\n        \"Porque vive dentro de fósseis\",\n        \"Porque sua concha é feita de pedra\",\n        \"Porque só existe em museus\"\n      ],\n      \"c\": 0,\n      \"e\": \"Ele tem uma concha em espiral e pertence a um grupo muito antigo de animais.\"\n    },\n    {\n      \"p\": \"A orca pertence a qual grupo?\",\n      \"o\": [\n        \"Família dos golfinhos\",\n        \"Família dos tubarões\",\n        \"Família das focas\",\n        \"Família das baleias-azuis\"\n      ],\n      \"c\": 0,\n      \"e\": \"A orca é o maior membro da família dos golfinhos.\"\n    },\n    {\n      \"p\": \"Qual é a característica mais marcante do tubarão-martelo?\",\n      \"o\": [\n        \"Cabeça achatada em forma de martelo\",\n        \"Bico em forma de espada\",\n        \"Corpo coberto de espinhos\",\n        \"Quatro nadadeiras dorsais\"\n      ],\n      \"c\": 0,\n      \"e\": \"O nome vem do formato da cabeça, larga e achatada.\"\n    },\n    {\n      \"p\": \"Quantos braços a estrela-do-mar-girassol pode ter?\",\n      \"o\": [\n        \"Mais de 20\",\n        \"Apenas 5\",\n        \"Apenas 2\",\n        \"Nenhum\"\n      ],\n      \"c\": 0,\n      \"e\": \"Ela é uma das maiores estrelas-do-mar e pode ter até cerca de 24 braços.\"\n    },\n    {\n      \"p\": \"O que a lula-gigante tem de enorme?\",\n      \"o\": [\n        \"Os olhos\",\n        \"As nadadeiras\",\n        \"Os dentes\",\n        \"A cauda\"\n      ],\n      \"c\": 0,\n      \"e\": \"Seus olhos estão entre os maiores do reino animal, com cerca de 25 centímetros.\"\n    },\n    {\n      \"p\": \"O que o tubarão-branco tem na boca?\",\n      \"o\": [\n        \"Várias fileiras de dentes serrilhados\",\n        \"Apenas um par de presas\",\n        \"Uma placa sem dentes\",\n        \"Dentes que nunca caem\"\n      ],\n      \"c\": 0,\n      \"e\": \"Quando um dente cai, outro da fileira de trás ocupa o lugar.\"\n    },\n    {\n      \"p\": \"Onde a moreia costuma se esconder?\",\n      \"o\": [\n        \"Em tocas e fendas de rochas e recifes\",\n        \"Enterrada na areia o tempo todo\",\n        \"Entre algas flutuantes\",\n        \"Em mar aberto, longe da costa\"\n      ],\n      \"c\": 0,\n      \"e\": \"Ela fica escondida em tocas e sai para caçar.\"\n    },\n    {\n      \"p\": \"Como a raia-manta nada?\",\n      \"o\": [\n        \"Movimentando as grandes nadadeiras como asas\",\n        \"Batendo a cauda de um lado para o outro\",\n        \"Expulsando água como um jato\",\n        \"Rastejando no fundo\"\n      ],\n      \"c\": 0,\n      \"e\": \"Suas nadadeiras largas lembram asas e dão a ela um nado gracioso.\"\n    },\n    {\n      \"p\": \"Qual peixe tem o focinho alongado em forma de espada?\",\n      \"o\": [\n        \"Peixe-espada (espadarte)\",\n        \"Barracuda\",\n        \"Moreia\",\n        \"Peixe-palhaço\"\n      ],\n      \"c\": 0,\n      \"e\": \"O espadarte usa o focinho alongado e é um nadador muito veloz.\"\n    },\n    {\n      \"p\": \"O golfinho-nariz-de-garrafa é…\",\n      \"o\": [\n        \"Um mamífero\",\n        \"Um peixe\",\n        \"Um réptil\",\n        \"Um molusco\"\n      ],\n      \"c\": 0,\n      \"e\": \"Golfinhos respiram ar, amamentam os filhotes e são mamíferos.\"\n    },\n    {\n      \"p\": \"O que a tartaruga-verde adulta come principalmente?\",\n      \"o\": [\n        \"Algas e plantas marinhas\",\n        \"Águas-vivas\",\n        \"Peixes grandes\",\n        \"Corais\"\n      ],\n      \"c\": 0,\n      \"e\": \"Os filhotes comem de tudo um pouco, mas os adultos são principalmente herbívoros.\"\n    }\n  ],\n  \"dinossauros\": [\n    {\n      \"p\": \"O que significa o nome Tyrannosaurus rex?\",\n      \"o\": [\n        \"Rei dos lagartos tiranos\",\n        \"Lagarto de três chifres\",\n        \"Garra terrível\",\n        \"Ladrão veloz\"\n      ],\n      \"c\": 0,\n      \"e\": \"O nome vem do grego e do latim e quer dizer “rei dos lagartos tiranos”.\"\n    },\n    {\n      \"p\": \"Quantos chifres tinha o Triceratops?\",\n      \"o\": [\n        \"Três\",\n        \"Dois\",\n        \"Cinco\",\n        \"Nenhum\"\n      ],\n      \"c\": 0,\n      \"e\": \"O nome significa “rosto com três chifres”.\"\n    },\n    {\n      \"p\": \"Onde foram encontrados principalmente os fósseis do Velociraptor?\",\n      \"o\": [\n        \"Mongólia\",\n        \"Brasil\",\n        \"Canadá\",\n        \"Austrália\"\n      ],\n      \"c\": 0,\n      \"e\": \"Seus fósseis foram achados principalmente na Mongólia.\"\n    },\n    {\n      \"p\": \"Qual destes é um dos maiores dinossauros terrestres já conhecidos?\",\n      \"o\": [\n        \"Argentinossauro\",\n        \"Compsognato\",\n        \"Microraptor\",\n        \"Velociraptor\"\n      ],\n      \"c\": 0,\n      \"e\": \"As estimativas indicam um gigante de mais de 30 metros, encontrado na Argentina.\"\n    },\n    {\n      \"p\": \"Qual destes era um dos menores dinossauros carnívoros?\",\n      \"o\": [\n        \"Compsognato\",\n        \"Giganotossauro\",\n        \"Espinossauro\",\n        \"Tiranossauro rex\"\n      ],\n      \"c\": 0,\n      \"e\": \"O Compsognato tinha cerca de 1 metro de comprimento.\"\n    },\n    {\n      \"p\": \"O que o Estegossauro tinha nas costas e na cauda?\",\n      \"o\": [\n        \"Placas e espinhos\",\n        \"Uma vela\",\n        \"Uma clava\",\n        \"Penas longas\"\n      ],\n      \"c\": 0,\n      \"e\": \"Ele tinha placas ao longo das costas e espinhos na cauda.\"\n    },\n    {\n      \"p\": \"Qual dinossauro tinha uma clava óssea na ponta da cauda?\",\n      \"o\": [\n        \"Anquilossauro\",\n        \"Estegossauro\",\n        \"Triceratops\",\n        \"Iguanodonte\"\n      ],\n      \"c\": 0,\n      \"e\": \"O Anquilossauro era blindado e usava a clava para se defender.\"\n    },\n    {\n      \"p\": \"Qual dinossauro tinha uma grande vela nas costas?\",\n      \"o\": [\n        \"Espinossauro\",\n        \"Tiranossauro rex\",\n        \"Triceratops\",\n        \"Galimimo\"\n      ],\n      \"c\": 0,\n      \"e\": \"O Espinossauro tinha uma vela nas costas e hábitos ligados à água.\"\n    },\n    {\n      \"p\": \"Por que o Archaeopteryx é tão importante?\",\n      \"o\": [\n        \"Liga os dinossauros às aves modernas\",\n        \"Foi o maior dinossauro\",\n        \"Vivia no fundo do mar\",\n        \"Era o maior predador\"\n      ],\n      \"c\": 0,\n      \"e\": \"Ele tinha penas e asas, mas também dentes e cauda longa, como um dinossauro.\"\n    },\n    {\n      \"p\": \"Por que o Microraptor parecia ter quatro asas?\",\n      \"o\": [\n        \"Tinha penas nos braços e nas pernas\",\n        \"Tinha dois pares de braços\",\n        \"Tinha uma membrana como a dos morcegos\",\n        \"Tinha asas saindo das costelas\"\n      ],\n      \"c\": 0,\n      \"e\": \"Penas longas nos quatro membros davam a ele essa aparência.\"\n    },\n    {\n      \"p\": \"O que o Parassaurolofo tinha na cabeça?\",\n      \"o\": [\n        \"Uma longa crista oca\",\n        \"Três chifres\",\n        \"Uma cúpula óssea\",\n        \"Dois espinhos no nariz\"\n      ],\n      \"c\": 0,\n      \"e\": \"A crista pode ter servido para emitir sons e se comunicar.\"\n    },\n    {\n      \"p\": \"Qual dinossauro tinha o crânio grosso em forma de cúpula?\",\n      \"o\": [\n        \"Paquicefalossauro\",\n        \"Parassaurolofo\",\n        \"Carnotauro\",\n        \"Oviraptor\"\n      ],\n      \"c\": 0,\n      \"e\": \"O nome significa “lagarto de cabeça grossa”.\"\n    },\n    {\n      \"p\": \"O que o Terizinossauro tinha de mais impressionante?\",\n      \"o\": [\n        \"Garras gigantescas nas mãos\",\n        \"Uma clava na cauda\",\n        \"Um chifre no nariz\",\n        \"Asas com penas longas\"\n      ],\n      \"c\": 0,\n      \"e\": \"Suas garras podiam chegar a cerca de 50 centímetros.\"\n    },\n    {\n      \"p\": \"O que o Iguanodonte tinha no lugar dos polegares?\",\n      \"o\": [\n        \"Espinhos\",\n        \"Garras em forma de foice\",\n        \"Placas\",\n        \"Penas\"\n      ],\n      \"c\": 0,\n      \"e\": \"Os espinhos nos polegares são a marca mais conhecida do Iguanodonte.\"\n    },\n    {\n      \"p\": \"Nos filmes, o Dilofossauro cospe veneno. O que se sabe sobre isso?\",\n      \"o\": [\n        \"Não há provas de que ele fazia isso\",\n        \"Estudos comprovaram que cuspia\",\n        \"Só cuspia quando estava com fome\",\n        \"Só cuspia quando era filhote\"\n      ],\n      \"c\": 0,\n      \"e\": \"O veneno e a gola foram invenções do cinema.\"\n    },\n    {\n      \"p\": \"Por que o Oviraptor recebeu o nome “ladrão de ovos”?\",\n      \"o\": [\n        \"Foi achado junto a ovos e acharam que os roubava\",\n        \"Só comia ovos de outros dinossauros\",\n        \"Vivia dentro de ninhos de aves\",\n        \"Colocava seus ovos em ninhos alheios\"\n      ],\n      \"c\": 0,\n      \"e\": \"Foi um engano: hoje se acredita que os ovos eram da própria família dele e que ele os chocava.\"\n    },\n    {\n      \"p\": \"Em qual período viveu o Tiranossauro rex?\",\n      \"o\": [\n        \"Cretáceo\",\n        \"Triássico\",\n        \"Jurássico\",\n        \"Permiano\"\n      ],\n      \"c\": 0,\n      \"e\": \"Ele viveu há cerca de 68 a 66 milhões de anos, no fim do período Cretáceo.\"\n    },\n    {\n      \"p\": \"Qual dinossauro lembrava um avestruz e corria muito rápido?\",\n      \"o\": [\n        \"Galimimo\",\n        \"Anquilossauro\",\n        \"Estegossauro\",\n        \"Braquiossauro\"\n      ],\n      \"c\": 0,\n      \"e\": \"O nome Galimimo significa “imitador de galinha”.\"\n    },\n    {\n      \"p\": \"O que o Carnotauro tinha acima dos olhos?\",\n      \"o\": [\n        \"Dois pequenos chifres\",\n        \"Uma crista oca\",\n        \"Uma vela\",\n        \"Um bico de pato\"\n      ],\n      \"c\": 0,\n      \"e\": \"Seu nome significa “touro carnívoro” e seus braços eram minúsculos.\"\n    },\n    {\n      \"p\": \"Qual destes dinossauros tinha o pescoço muito longo?\",\n      \"o\": [\n        \"Diplodoco\",\n        \"Tiranossauro rex\",\n        \"Velociraptor\",\n        \"Compsognato\"\n      ],\n      \"c\": 0,\n      \"e\": \"O Diplodoco era um saurópode, com pescoço e cauda muito longos.\"\n    }\n  ]\n};\n\nconst POR_RODADA = 10;\nconst NOMES = { biologia: 'Biologia Marinha', dinossauros: 'Dinossauros' };\n\nconst $ = (id) => document.getElementById(id);\nconst principal = $('quiz');\n\nlet area = null;\nlet rodada = [];\nlet indice = 0;\nlet pontos = 0;\nlet respondida = false;\n\nfunction embaralhar(lista) {\n  const a = lista.slice();\n  for (let i = a.length - 1; i > 0; i--) {\n    const j = Math.floor(Math.random() * (i + 1));\n    [a[i], a[j]] = [a[j], a[i]];\n  }\n  return a;\n}\n\nfunction lerRecorde(a) {\n  try { const v = localStorage.getItem('quiz-recorde-' + a); return v === null ? null : Number(v); } catch (e) { return null; }\n}\nfunction gravarRecorde(a, v) {\n  try { localStorage.setItem('quiz-recorde-' + a, String(v)); } catch (e) { /* sem armazenamento: tudo bem */ }\n}\n\nfunction mostrarRecordes() {\n  for (const a of Object.keys(NOMES)) {\n    const r = lerRecorde(a);\n    $('recorde-' + a).textContent = r === null ? '' : 'Seu recorde: ' + r + '/' + POR_RODADA;\n  }\n}\n\nfunction mostrarTela(nome) {\n  $('tela-escolha').hidden = nome !== 'escolha';\n  $('tela-pergunta').hidden = nome !== 'pergunta';\n  $('tela-final').hidden = nome !== 'final';\n}\n\nfunction iniciar(novaArea) {\n  area = novaArea;\n  principal.className = area === 'biologia' ? 'marinha' : 'dinossauros';\n  rodada = embaralhar(PERGUNTAS[area]).slice(0, POR_RODADA).map((q) => ({\n    pergunta: q.p,\n    explicacao: q.e,\n    opcoes: embaralhar(q.o.map((texto, i) => ({ texto, certa: i === q.c }))),\n  }));\n  indice = 0;\n  pontos = 0;\n  mostrarTela('pergunta');\n  mostrarPergunta();\n}\n\nfunction mostrarPergunta() {\n  const q = rodada[indice];\n  respondida = false;\n\n  $('quiz-progresso').textContent = 'Pergunta ' + (indice + 1) + ' de ' + rodada.length;\n  $('quiz-pontos').textContent = 'Acertos: ' + pontos;\n  $('quiz-barra-cheia').style.width = (indice / rodada.length) * 100 + '%';\n  $('quiz-enunciado').textContent = q.pergunta;\n  $('quiz-explicacao').hidden = true;\n  $('quiz-proxima').hidden = true;\n\n  const caixa = $('quiz-opcoes');\n  caixa.textContent = '';\n  q.opcoes.forEach((op) => {\n    const b = document.createElement('button');\n    b.type = 'button';\n    b.className = 'quiz-opcao';\n    b.textContent = op.texto;\n    b.addEventListener('click', () => responder(b, op));\n    caixa.appendChild(b);\n  });\n}\n\nfunction responder(botao, opcao) {\n  if (respondida) return;\n  respondida = true;\n  const q = rodada[indice];\n\n  if (opcao.certa) pontos++;\n\n  const botoes = Array.from($('quiz-opcoes').children);\n  botoes.forEach((b, i) => {\n    b.disabled = true;\n    if (q.opcoes[i].certa) b.classList.add('certa');\n  });\n  if (!opcao.certa) botao.classList.add('errada');\n\n  const exp = $('quiz-explicacao');\n  exp.textContent = (opcao.certa ? '✅ Correto! ' : '❌ Não foi dessa vez. ') + q.explicacao;\n  exp.hidden = false;\n\n  $('quiz-pontos').textContent = 'Acertos: ' + pontos;\n  $('quiz-barra-cheia').style.width = ((indice + 1) / rodada.length) * 100 + '%';\n\n  const proxima = $('quiz-proxima');\n  proxima.textContent = indice === rodada.length - 1 ? 'Ver resultado' : 'Próxima pergunta →';\n  proxima.hidden = false;\n  proxima.focus();\n}\n\nfunction proxima() {\n  if (indice < rodada.length - 1) {\n    indice++;\n    mostrarPergunta();\n  } else {\n    terminar();\n  }\n}\n\nfunction terminar() {\n  const total = rodada.length;\n  $('quiz-placar').textContent = 'Você acertou ' + pontos + ' de ' + total + ' perguntas';\n\n  let msg;\n  const prop = pontos / total;\n  if (prop === 1) msg = 'Perfeito! Você é um expert em ' + NOMES[area] + '! 🏆';\n  else if (prop >= 0.7) msg = 'Muito bem! Você conhece bastante sobre o assunto. 👏';\n  else if (prop >= 0.5) msg = 'Bom resultado! Explore as páginas do site e tente de novo. 🙂';\n  else msg = 'Continue explorando o site e tente outra vez. Você consegue! 💪';\n  $('quiz-mensagem').textContent = msg;\n\n  const antigo = lerRecorde(area);\n  if (antigo === null || pontos > antigo) {\n    gravarRecorde(area, pontos);\n    $('quiz-recorde-final').textContent = antigo === null ? 'Primeiro recorde registrado: ' + pontos + '/' + total : '🎉 Novo recorde: ' + pontos + '/' + total + '!';\n  } else {\n    $('quiz-recorde-final').textContent = 'Seu recorde: ' + antigo + '/' + total;\n  }\n\n  mostrarTela('final');\n}\n\nfunction voltarAoInicio() {\n  principal.className = '';\n  area = null;\n  mostrarRecordes();\n  mostrarTela('escolha');\n}\n\ndocument.querySelectorAll('.quiz-area').forEach((b) => b.addEventListener('click', () => iniciar(b.dataset.area)));\n$('quiz-proxima').addEventListener('click', proxima);\n$('quiz-repetir').addEventListener('click', () => iniciar(area));\n$('quiz-trocar').addEventListener('click', voltarAoInicio);\n\nmostrarRecordes();\n";
const FUNDO_BIOLOGIA_B64 = '';
const FUNDO_DINOSSAUROS_B64 = '';

const dormir = (ms) => new Promise((r) => setTimeout(r, ms));
const ler = (f) => fs.readFileSync(f, 'utf8');
const gravar = (f, t) => fs.writeFileSync(f, t, 'utf8');
const semHtml = (s) => String(s || '').replace(/<[^>]*>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' ').replace(/\s+/g, ' ').trim();

async function pedir(url, tentativas = 4) {
  for (let i = 0; i < tentativas; i++) {
    const r = await fetch(url, { headers: { 'User-Agent': UA } });
    if (r.status === 429 || r.status >= 500) { await dormir(2000 * (i + 1)); continue; }
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return r;
  }
  throw new Error('muitas tentativas');
}

// ----------------------------------------------------------- 3. Diplodoco
async function trocarDiplodoco(avisos) {
  const candidatos = ['File:DiplodocusDB.jpg', 'File:Diplodocus cknight.jpg'];
  const EXT = { 'image/jpeg': '.jpg', 'image/png': '.png', 'image/webp': '.webp' };
  for (const titulo of candidatos) {
    try {
      const api = 'https://commons.wikimedia.org/w/api.php?action=query&format=json&prop=imageinfo' +
        '&iiprop=url|mime|size|extmetadata&iiurlwidth=900&iiextmetadatafilter=Artist|LicenseShortName' +
        '&titles=' + encodeURIComponent(titulo);
      const dados = await (await pedir(api)).json();
      const pagina = Object.values((dados.query && dados.query.pages) || {})[0];
      const info = pagina && pagina.imageinfo && pagina.imageinfo[0];
      if (!info || !info.thumburl) continue;

      const r = await pedir(info.thumburl);
      const tipo = (r.headers.get('content-type') || '').split(';')[0].trim();
      const ext = EXT[tipo] || '.jpg';
      fs.mkdirSync(IMAGENS, { recursive: true });
      for (const f of fs.readdirSync(IMAGENS)) if (path.parse(f).name === 'diplodoco') fs.unlinkSync(path.join(IMAGENS, f));
      const nome = 'diplodoco' + ext;
      fs.writeFileSync(path.join(IMAGENS, nome), Buffer.from(await r.arrayBuffer()));

      for (const f of [path.join(PUBLIC, 'dinossauros.html'), path.join(PUBLIC, 'dinossauros', 'diplodoco.html')]) {
        if (!fs.existsSync(f)) continue;
        const txt = ler(f);
        const novo = txt.replace(/imagens\/diplodoco\.[a-z0-9]+/g, 'imagens/' + nome);
        if (novo !== txt) gravar(f, novo);
      }

      const meta = info.extmetadata || {};
      const bloco = 'diplodoco: ' + titulo + '\n   https://commons.wikimedia.org/wiki/' + encodeURI(titulo.replace(/ /g, '_')) +
        '\n   Autor: ' + (semHtml(meta.Artist && meta.Artist.value) || 'ver página') +
        ' | Licença: ' + (semHtml(meta.LicenseShortName && meta.LicenseShortName.value) || 'ver página');
      const cred = path.join(IMAGENS, 'CREDITOS.txt');
      if (fs.existsSync(cred)) {
        let c = ler(cred);
        c = /^diplodoco:[^\n]*\n[^\n]*\n[^\n]*/m.test(c) ? c.replace(/^diplodoco:[^\n]*\n[^\n]*\n[^\n]*/m, bloco) : c + '\n' + bloco + '\n';
        gravar(cred, c);
      }
      return nome;
    } catch (e) {
      avisos.push('Diplodoco: ' + titulo + ' falhou (' + e.message + ')');
    }
  }
  return null;
}

// ------------------------------------------------------------ menus / páginas
function adicionarLinkQuiz(txt, prefixo) {
  return txt.replace(/<nav>([\s\S]*?)<\/nav>/, (m, inner) => {
    if (/quiz\.html/.test(inner)) return m;
    const mm = inner.match(/\n([ \t]*)<a [^>]*>[^<]*<\/a>\s*$/);
    const indent = mm ? mm[1] : '            ';
    const corpo = inner.replace(/\s*$/, '');
    const fim = inner.slice(corpo.length);
    return `<nav>${corpo}\n${indent}<a href="${prefixo}quiz.html">Quiz</a>${fim}</nav>`;
  });
}

function listarHtml(pasta) {
  const dir = path.join(PUBLIC, pasta);
  return fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.endsWith('.html')).map((f) => path.join(dir, f)) : [];
}

async function principal() {
  if (!fs.existsSync(PUBLIC)) {
    console.log('ERRO: não achei a pasta "public". Rode este comando dentro da pasta do projeto (onde fica o server.js).');
    return;
  }
  const avisos = [];

  // 0. backup
  if (!fs.existsSync(BACKUP)) { fs.cpSync(PUBLIC, BACKUP, { recursive: true }); console.log('Backup criado em: public_backup_antes_do_quiz\n'); }
  else console.log('(o backup já existia, mantido como está)\n');

  // 1. fundos + css
  console.log('PASSO 1: fundos e ajustes de estilo...');
  fs.mkdirSync(IMAGENS, { recursive: true });
  fs.writeFileSync(path.join(IMAGENS, 'fundo-biologia.png'), Buffer.from(FUNDO_BIOLOGIA_B64, 'base64'));
  fs.writeFileSync(path.join(IMAGENS, 'fundo-dinossauros.png'), Buffer.from(FUNDO_DINOSSAUROS_B64, 'base64'));

  const fcss = path.join(PUBLIC, 'style.css');
  if (!fs.existsSync(fcss)) avisos.push('FALTA public/style.css');
  else {
    let css = ler(fcss);
    const i = css.indexOf(MARCA_CSS);
    if (i !== -1) css = css.slice(0, i).replace(/\s*$/, '\n'); // reaplica a versão mais nova
    gravar(fcss, css + '\n' + CSS);
    console.log('  style.css atualizado.');
  }

  // classe "marinha" (liga o fundo azul) nas páginas de Biologia Marinha
  let marinhas = 0;
  for (const f of [path.join(PUBLIC, 'biologia.html'), ...listarHtml('biologia')]) {
    if (!fs.existsSync(f)) continue;
    const txt = ler(f);
    if (/class="marinha"/.test(txt)) { marinhas++; continue; }
    if (/<main>/.test(txt)) { gravar(f, txt.replace('<main>', '<main class="marinha">')); marinhas++; }
    else avisos.push(path.relative(PUBLIC, f) + ': <main> com classe diferente; fundo azul não aplicado nela');
  }
  console.log(`  fundo azul ligado em ${marinhas} páginas de Biologia Marinha.`);

  // 2/3. fotos
  console.log('\nPASSO 2: foto do Diplodoco...');
  const dip = await trocarDiplodoco(avisos);
  console.log(dip ? '  Diplodoco trocado -> imagens/' + dip : '  não consegui baixar (veja os avisos no final).');

  // 4. quiz
  console.log('\nPASSO 3: criando o quiz...');
  gravar(path.join(PUBLIC, 'quiz.html'), QUIZ_HTML);
  gravar(path.join(PUBLIC, 'quiz.js'), QUIZ_JS);
  console.log('  quiz.html e quiz.js criados.');

  let menus = 0;
  const alvos = [
    [path.join(PUBLIC, 'index.html'), ''],
    [path.join(PUBLIC, 'biologia.html'), ''],
    [path.join(PUBLIC, 'dinossauros.html'), ''],
    ...listarHtml('biologia').map((f) => [f, '../']),
    ...listarHtml('dinossauros').map((f) => [f, '../']),
  ];
  for (const [f, pre] of alvos) {
    if (!fs.existsSync(f)) continue;
    const txt = ler(f);
    const novo = adicionarLinkQuiz(txt, pre);
    if (novo !== txt) { gravar(f, novo); menus++; }
  }
  console.log(`  link "Quiz" adicionado ao menu de ${menus} páginas.`);

  // card na página inicial
  const fi = path.join(PUBLIC, 'index.html');
  if (fs.existsSync(fi)) {
    const txt = ler(fi);
    if (/href="quiz\.html" class="opcao"/.test(txt)) console.log('  card do quiz já existe na página inicial.');
    else {
      const card = `
                <a href="quiz.html" class="opcao">
                    <h3>🧠 Quiz</h3>
                    <p>
                        Teste o que você aprendeu
                        sobre os animais e os dinossauros.
                    </p>
                </a>`;
      const novo = txt.replace(/(<a href="dinossauros\.html" class="opcao">[\s\S]*?<\/a>)/, '$1' + card);
      if (novo !== txt) { gravar(fi, novo); console.log('  card do quiz adicionado na página inicial.'); }
      else avisos.push('index.html: não achei o card dos dinossauros para colocar o card do quiz depois dele');
    }
  }

  console.log('\n==================== PRONTO ====================');
  if (avisos.length) { console.log('Pontos para conferir:'); avisos.forEach((a) => console.log(' - ' + a)); }
  console.log('Agora é só atualizar o navegador com Ctrl+F5 (não precisa reiniciar o servidor).');
  console.log('O quiz fica em: http://localhost:3000/quiz.html');
}

principal();